custom_css:
/* 01-tokens.css */
:root {
    --ef-void: #101415;
    --ef-void-soft: #171b1c;
    /* 纸面、墨色与黄色取自官号长图实测：纸面中性白而非偏绿，黄色是纯黄。
       量法与数值见 references/UI_FACTS.md 的「官号长图实测」表。 */
    --ef-paper: #fdfdfd;
    --ef-paper-hi: #ffffff;
    --ef-workbench: #e5e5e5;
    --ef-ink: #061112;
    --ef-graphite: #25292a;
    --ef-muted: #707674;
    --ef-signal: #ffff0f;
    --ef-block: #444444;
    --ef-label: #888888;
    --ef-calib-m: #d025ce;
    --ef-calib-y: #fcf56d;
    --ef-calib-c: #34e3ad;
    --ef-line: rgba(23, 26, 26, 0.16);
    --ef-line-soft: rgba(23, 26, 26, 0.075);
    --ef-paper-grid: url("data:image/svg+xml,%3Csvg xmlns='http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg' width='160' height='160' viewBox='0 0 160 160'%3E%3Cdefs%3E%3Cpattern id='g' width='10' height='10' patternUnits='userSpaceOnUse'%3E%3Cpath d='M10 0H0V10' fill='none' stroke='%23171a1a' stroke-opacity='.018' stroke-width='.55'/%3E%3C/pattern%3E%3C/defs%3E%3Crect width='160' height='160' fill='url(%23g)'/%3E%3Cg fill='none' stroke='%23171a1a'%3E%3Cpath d='M0 .5H160M.5 0V160' stroke-opacity='.025' stroke-width='.65'/%3E%3Cpath d='M74 80H86M80 74V86' stroke-opacity='.09' stroke-width='.9'/%3E%3C/g%3E%3C/svg%3E");
    --ef-gray-grid: url("data:image/svg+xml,%3Csvg xmlns='http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg' width='160' height='160' viewBox='0 0 160 160'%3E%3Cg fill='none' stroke='%23434b49'%3E%3Cpath d='M0 .5H160M.5 0V160' stroke-opacity='.075' stroke-width='.75'/%3E%3Cpath d='M0 0L160 160M160 0L0 160' stroke-opacity='.018' stroke-width='.65'/%3E%3C/g%3E%3C/svg%3E");
    --ef-gray-hatch: repeating-linear-gradient(135deg, rgba(255, 255, 255, 0.16) 0 1px, transparent 1px 7px);
    --ef-section-hatch: repeating-linear-gradient(135deg, rgba(67, 75, 73, 0.075) 0 1px, transparent 1px 7px);
    --ef-contours: url("data:image/svg+xml,%3Csvg xmlns='http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg' width='280' height='90' viewBox='0 0 280 90'%3E%3Cg fill='none' stroke='%23171a1a' stroke-width='.75' opacity='.18'%3E%3Cpath d='M-10 54c32-27 56-29 80-6s54 25 79 4 53-25 78-6 45 21 69 4'/%3E%3Cpath d='M-12 64c33-29 61-31 87-7s48 22 72 2 54-29 82-8 45 20 64 7'/%3E%3Cpath d='M8 75c27-24 49-24 70-5s45 19 66 2 50-28 81-11 48 21 67 11'/%3E%3Cpath d='M21 34c20-17 35-17 51-3s34 15 49 3 37-20 59-7 37 14 57 5'/%3E%3C/g%3E%3C/svg%3E");
    --ef-hatch: repeating-linear-gradient(135deg, rgba(255, 255, 255, 0.018) 0 1px, transparent 1px 6px);
    --ef-icon-tune: url("data:image/svg+xml,%3Csvg xmlns='http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg' viewBox='0 0 24 24' fill='none' stroke='white' stroke-width='1.7' stroke-linecap='square' stroke-linejoin='miter'%3E%3Cpath d='M4 7h6m4 0h6M10 4v6M4 17h3m4 0h9M7 14v6'/%3E%3C/svg%3E");
    --ef-icon-plug: url("data:image/svg+xml,%3Csvg xmlns='http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg' viewBox='0 0 24 24' fill='none' stroke='white' stroke-width='1.7' stroke-linecap='square' stroke-linejoin='miter'%3E%3Cpath d='M8 3v5m8-5v5M6 8h12v3a6 6 0 0 1-6 6v4m-3 0h6'/%3E%3C/svg%3E");
    --ef-icon-type: url("data:image/svg+xml,%3Csvg xmlns='http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg' viewBox='0 0 24 24' fill='none' stroke='white' stroke-width='1.7' stroke-linecap='square' stroke-linejoin='miter'%3E%3Cpath d='M5 5h14M12 5v14M8 19h8'/%3E%3C/svg%3E");
    --ef-icon-book: url("data:image/svg+xml,%3Csvg xmlns='http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg' viewBox='0 0 24 24' fill='none' stroke='white' stroke-width='1.7' stroke-linecap='square' stroke-linejoin='miter'%3E%3Cpath d='M4 5.5A2.5 2.5 0 0 1 6.5 3H11v16H6.5A2.5 2.5 0 0 0 4 21V5.5Zm16 0A2.5 2.5 0 0 0 17.5 3H13v16h4.5A2.5 2.5 0 0 1 20 21V5.5Z'/%3E%3C/svg%3E");
    --ef-icon-settings: url("data:image/svg+xml,%3Csvg xmlns='http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg' viewBox='0 0 24 24' fill='none' stroke='white' stroke-width='1.7' stroke-linecap='square' stroke-linejoin='miter'%3E%3Cpath d='M12 3l7 4v10l-7 4-7-4V7l7-4Z'/%3E%3Ccircle cx='12' cy='12' r='3'/%3E%3C/svg%3E");
    --ef-icon-image: url("data:image/svg+xml,%3Csvg xmlns='http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg' viewBox='0 0 24 24' fill='none' stroke='white' stroke-width='1.7' stroke-linecap='square' stroke-linejoin='miter'%3E%3Crect x='3' y='4' width='18' height='16'/%3E%3Ccircle cx='8' cy='9' r='1.5'/%3E%3Cpath d='M5 18l4-5 3 3 3-4 4 6'/%3E%3C/svg%3E");
    --ef-icon-modules: url("data:image/svg+xml,%3Csvg xmlns='http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg' viewBox='0 0 24 24' fill='none' stroke='white' stroke-width='1.7' stroke-linecap='square' stroke-linejoin='miter'%3E%3Cpath d='M4 4h6v6H4V4Zm10 0h6v6h-6V4ZM4 14h6v6H4v-6Zm10 0h6v6h-6v-6Z'/%3E%3C/svg%3E");
    --ef-icon-persona: url("data:image/svg+xml,%3Csvg xmlns='http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg' viewBox='0 0 24 24' fill='none' stroke='white' stroke-width='1.7' stroke-linecap='square' stroke-linejoin='miter'%3E%3Ccircle cx='12' cy='8' r='4'/%3E%3Cpath d='M5 21v-2a7 7 0 0 1 14 0v2'/%3E%3C/svg%3E");
    --ef-icon-archive: url("data:image/svg+xml,%3Csvg xmlns='http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg' viewBox='0 0 24 24' fill='none' stroke='white' stroke-width='1.7' stroke-linecap='square' stroke-linejoin='miter'%3E%3Crect x='3' y='5' width='18' height='14'/%3E%3Ccircle cx='9' cy='11' r='2'/%3E%3Cpath d='M6 16c.8-1.7 2-2.5 3-2.5s2.2.8 3 2.5M14 10h4M14 14h4'/%3E%3C/svg%3E");
    --ef-icon-menu: url("data:image/svg+xml,%3Csvg xmlns='http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg' viewBox='0 0 24 24' fill='none' stroke='white' stroke-width='1.7' stroke-linecap='square' stroke-linejoin='miter'%3E%3Cpath d='M4 6h16M4 12h11M4 18h16'/%3E%3C/svg%3E");
    --ef-icon-spark: url("data:image/svg+xml,%3Csvg xmlns='http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg' viewBox='0 0 24 24' fill='none' stroke='white' stroke-width='1.7' stroke-linecap='square' stroke-linejoin='miter'%3E%3Cpath d='M12 3l1.3 3.7L17 8l-3.7 1.3L12 13l-1.3-3.7L7 8l3.7-1.3L12 3ZM18.5 14l.7 2.1 2.1.7-2.1.7-.7 2.1-.7-2.1-2.1-.7 2.1-.7.7-2.1ZM5 14l.8 2.2L8 17l-2.2.8L5 20l-.8-2.2L2 17l2.2-.8L5 14Z'/%3E%3C/svg%3E");
    --ef-icon-action: url("data:image/svg+xml,%3Csvg xmlns='http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg' viewBox='0 0 24 24' fill='none' stroke='white' stroke-width='1.8' stroke-linecap='square' stroke-linejoin='miter'%3E%3Cpath d='M4 12h15M13 6l6 6-6 6'/%3E%3C/svg%3E");
    --ef-icon-import: url("data:image/svg+xml,%3Csvg xmlns='http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg' viewBox='0 0 24 24' fill='none' stroke='white' stroke-width='1.7' stroke-linecap='square' stroke-linejoin='miter'%3E%3Cpath d='M4 17v3h16v-3M12 3v11M8 10l4 4 4-4'/%3E%3C/svg%3E");
    --ef-icon-export: url("data:image/svg+xml,%3Csvg xmlns='http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg' viewBox='0 0 24 24' fill='none' stroke='white' stroke-width='1.7' stroke-linecap='square' stroke-linejoin='miter'%3E%3Cpath d='M4 17v3h16v-3M12 15V4M8 8l4-4 4 4'/%3E%3C/svg%3E");
    --ef-icon-trash: url("data:image/svg+xml,%3Csvg xmlns='http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg' viewBox='0 0 24 24' fill='none' stroke='white' stroke-width='1.7' stroke-linecap='square' stroke-linejoin='miter'%3E%3Cpath d='M5 7h14M9 7V4h6v3M7 7l1 13h8l1-13M10 10v7m4-7v7'/%3E%3C/svg%3E");
    --ef-icon-save: url("data:image/svg+xml,%3Csvg xmlns='http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg' viewBox='0 0 24 24' fill='none' stroke='white' stroke-width='1.7' stroke-linecap='square' stroke-linejoin='miter'%3E%3Cpath d='M5 3h11l3 3v15H5V3Zm3 0v6h8V3M8 14h8v7'/%3E%3C/svg%3E");
    --ef-icon-new-file: url("data:image/svg+xml,%3Csvg xmlns='http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg' viewBox='0 0 24 24' fill='none' stroke='white' stroke-width='1.7' stroke-linecap='square' stroke-linejoin='miter'%3E%3Cpath d='M6 3h8l4 4v14H6V3Zm8 0v5h5M9 14h6m-3-3v6'/%3E%3C/svg%3E");
    --ef-icon-account: url("data:image/svg+xml,%3Csvg xmlns='http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg' viewBox='0 0 24 24' fill='none' stroke='white' stroke-width='1.7' stroke-linecap='square' stroke-linejoin='miter'%3E%3Cpath d='M12 3l7 3v5c0 4.7-2.8 8.1-7 10-4.2-1.9-7-5.3-7-10V6l7-3Z'/%3E%3Ccircle cx='12' cy='9' r='2.2'/%3E%3Cpath d='M8.7 15.5c.8-1.8 1.9-2.7 3.3-2.7s2.5.9 3.3 2.7'/%3E%3C/svg%3E");
    --ef-font-display: "HarmonyOS Sans SC", "Noto Sans SC", "Microsoft YaHei UI", sans-serif;
    --ef-font-body: "Noto Sans SC", "HarmonyOS Sans SC", "Microsoft YaHei UI", sans-serif;
    --ef-font-number: Haettenschweiler, "Arial Narrow", "Roboto Condensed", sans-serif;
    --ef-fast: 140ms;
    --ef-shift: 190ms;
}

body {
    background-color: var(--ef-workbench) !important;
    background-image: var(--ef-gray-grid), var(--ef-gray-hatch) !important;
    background-size: 160px 160px, auto !important;
    background-position: 0 0, 0 0 !important;
    background-repeat: repeat, repeat !important;
    background-attachment: fixed, fixed !important;
    --SmartThemeBodyColor: #eef0ed !important;
    --SmartThemeEmColor: #b9bfbd !important;
    --SmartThemeUnderlineColor: var(--ef-signal) !important;
    --SmartThemeQuoteColor: var(--ef-signal) !important;
    --SmartThemeBlurTintColor: rgba(16, 20, 21, 0.94) !important;
    --SmartThemeChatTintColor: var(--ef-paper) !important;
    --SmartThemeUserMesBlurTintColor: transparent !important;
    --SmartThemeBotMesBlurTintColor: transparent !important;
    --SmartThemeBorderColor: rgba(238, 240, 237, 0.2) !important;
    --SmartThemeShadowColor: transparent !important;
    font-family: var(--ef-font-body) !important;
}

/* 02-foundation.css */
/* A bounded reading plane: the page is the signature, not a synthetic HUD. */
#top-bar,
#top-settings-holder,
#sheld {
    width: min(var(--sheldWidth), 1080px) !important;
    max-width: 1080px !important;
}

#top-bar {
    background: rgba(16, 20, 21, 0.96) !important;
    border: 0 !important;
    border-bottom: 1px solid rgba(238, 240, 237, 0.14) !important;
    border-radius: 0 !important;
    box-shadow: none !important;
    backdrop-filter: none !important;
}

#chat {
    isolation: isolate;
    box-sizing: border-box;
    padding-left: 9px !important;
    color: var(--ef-ink) !important;
    font-family: var(--ef-font-body) !important;
    text-shadow: none !important;
    background-color: var(--ef-paper) !important;
    background-image: var(--ef-paper-grid) !important;
    border: 0 !important;
    border-left: 1px solid rgba(23, 26, 26, 0.24) !important;
    border-right: 1px solid rgba(23, 26, 26, 0.24) !important;
    border-radius: 0 !important;
    box-shadow: inset 8px 0 0 var(--ef-signal) !important;
    backdrop-filter: none !important;
    -webkit-backdrop-filter: none !important;
}

#chat a {
    color: #415d5a !important;
    text-decoration-color: rgba(65, 93, 90, 0.48) !important;
    text-underline-offset: 0.18em;
}

#chat :is(.mes_text, .mes_reasoning) blockquote {
    margin: 0.75em 0 !important;
    padding: 0.55em 0.8em !important;
    color: #343b39 !important;
    background: rgba(23, 26, 26, 0.045) !important;
    border: 0 !important;
    border-left: 3px solid var(--ef-signal) !important;
    border-radius: 0 !important;
}

#chat :is(.mes_text, .mes_reasoning) :is(code, pre) {
    color: var(--ef-ink) !important;
    background: rgba(23, 26, 26, 0.06) !important;
    border-color: rgba(23, 26, 26, 0.16) !important;
    border-radius: 0 !important;
    text-shadow: none !important;
}

#top-settings-holder > .drawer > .drawer-toggle {
    position: relative;
    color: rgba(238, 240, 237, 0.62) !important;
    background: transparent !important;
    border: 0 !important;
    border-radius: 0 !important;
    box-shadow: none !important;
    transition: color var(--ef-fast) ease-out, background-color var(--ef-fast) ease-out;
}

#top-settings-holder > .drawer > .drawer-toggle::after {
    content: "";
    position: absolute;
    right: 50%;
    bottom: 0;
    left: 50%;
    height: 2px;
    background: var(--ef-signal);
    transition: right var(--ef-shift) ease-out, left var(--ef-shift) ease-out;
}

#top-settings-holder > .drawer > .drawer-toggle:hover,
#top-settings-holder > .drawer > .drawer-toggle:focus-within {
    color: var(--ef-paper-hi) !important;
    background: rgba(255, 255, 255, 0.035) !important;
}

#top-settings-holder > .drawer > .drawer-toggle:hover::after,
#top-settings-holder > .drawer > .drawer-toggle:focus-within::after {
    right: 20%;
    left: 20%;
}

@media (max-width: 700px) {
    #top-bar,
    #top-settings-holder,
    #sheld {
        width: 100% !important;
        max-width: none !important;
    }

    #chat {
        padding-left: 6px !important;
        border-inline: 0 !important;
        box-shadow: inset 5px 0 0 var(--ef-signal) !important;
    }
}

/* 03-chat.css */
/* Keep SillyTavern's native flex message skeleton and restyle its real nodes. */
#chat > .mes {
    box-sizing: border-box;
    /* #chat is a fixed-height flex column: without this, messages shrink to
       min-height and their text spills over the following message. */
    flex-shrink: 0;
    min-height: 104px;
    margin: 0 !important;
    padding: 18px 22px 18px 18px !important;
    color: var(--ef-ink) !important;
    background: transparent !important;
    border: 0 !important;
    border-bottom: 1px solid var(--ef-line) !important;
    box-shadow: none !important;
    text-shadow: none !important;
    transition: background-color var(--ef-fast) ease-out;
}

#chat > .mes:hover,
#chat > .mes:focus-within {
    background-color: rgba(255, 255, 255, 0.34) !important;
}

#chat > .mes:not(.smallSysMes) > .mesAvatarWrapper {
    position: relative;
    box-sizing: border-box;
    display: flex;
    flex: 0 0 88px;
    flex-direction: column;
    align-items: flex-start;
    min-width: 0;
    padding: 0 20px 0 0 !important;
    color: var(--ef-muted) !important;
    border-right: 1px solid var(--ef-line) !important;
}

#chat > .last_mes:not(.smallSysMes) > .mesAvatarWrapper {
    padding-bottom: 0 !important;
}

#chat > .mes:not(.smallSysMes) > .mesAvatarWrapper::after {
    content: "";
    width: 18px;
    height: 3px;
    margin-top: 10px;
    background: var(--ef-signal);
}

#chat > .mes:not(.smallSysMes) > .mesAvatarWrapper .avatar,
#chat > .mes:not(.smallSysMes) > .mesAvatarWrapper .avatar img {
    box-sizing: border-box;
    width: 50px !important;
    height: 50px !important;
    min-width: 50px;
    min-height: 50px;
    border-radius: 0 !important;
}

#chat > .mes:not(.smallSysMes) > .mesAvatarWrapper .avatar {
    flex: 0 0 50px !important;
    filter: grayscale(0.2) contrast(1.04);
    background: var(--ef-graphite) !important;
}

#chat > .mes:not(.smallSysMes) > .mesAvatarWrapper .avatar img {
    object-fit: cover;
    border: 1px solid rgba(23, 26, 26, 0.32) !important;
    box-shadow: none !important;
}

#chat > .mes:not(.smallSysMes) > .mesAvatarWrapper :is(.mesIDDisplay, .mes_timer, .tokenCounterDisplay) {
    max-width: 66px;
    margin: 5px 0 0 !important;
    color: var(--ef-muted) !important;
    font: 600 10px/1.25 var(--ef-font-number) !important;
    letter-spacing: 0.035em;
    text-align: left !important;
    text-shadow: none !important;
}

#chat > .mes:not(.smallSysMes) > .mes_block {
    position: relative;
    box-sizing: border-box;
    flex: 1 1 auto;
    min-width: 0;
    padding: 0 0 0 20px !important;
    overflow-x: hidden;
    color: var(--ef-ink) !important;
}

#chat > .mes .ch_name {
    position: relative;
    min-height: 26px;
    padding: 0 0 8px !important;
    color: var(--ef-ink) !important;
    border-bottom: 1px solid var(--ef-line-soft);
}

#chat > .mes .ch_name .name_text {
    position: relative;
    z-index: 1;
    color: var(--ef-ink) !important;
    font-family: var(--ef-font-display) !important;
    font-size: 1.12em;
    font-weight: 800 !important;
    letter-spacing: 0.025em;
}

#chat > .mes[is_user="false"]:not([is_system="true"]) .ch_name .name_text {
    display: inline-block;
    padding: 2px 7px 2px 6px;
    color: var(--ef-ink) !important;
    background: var(--ef-signal);
}

#chat > .mes[is_user="false"]:not([is_system="true"]) .ch_name .name_text::before {
    content: "[";
}

#chat > .mes[is_user="false"]:not([is_system="true"]) .ch_name .name_text::after {
    content: "]";
}

/* 时间戳含"年月日"，条件字体没有 CJK 字形会宽窄混杂，改用正文字体等宽数字。 */
#chat > .mes .timestamp {
    margin-left: 8px;
    color: var(--ef-muted) !important;
    font: 500 10px/1 var(--ef-font-body) !important;
    font-variant-numeric: tabular-nums !important;
    letter-spacing: 0.02em;
    text-shadow: none !important;
}

/* 官方长图正文基线距 42px／字高 26px = 1.6；原 1.75 偏松，压紧后层级更清楚。 */
#chat > .mes .mes_text {
    padding: 12px var(--mes-right-spacing) 4px 0 !important;
    color: var(--ef-ink) !important;
    font-family: var(--ef-font-body) !important;
    font-weight: 470 !important;
    line-height: 1.6 !important;
}

#chat > .mes[is_user="false"] .mes_text :is(em, i) {
    color: #4f5754 !important;
}

#chat > .mes[is_user="false"] .mes_text q {
    color: #303735 !important;
    font-weight: 650 !important;
}

#chat > .mes .mes_buttons,
#chat > .mes .extraMesButtons,
#chat > .mes .mes_edit_buttons,
#chat > .mes .mes_reasoning_actions {
    color: var(--ef-ink) !important;
    text-shadow: none !important;
}

#chat > .mes :is(.mes_button, .extraMesButtons > div) {
    color: inherit !important;
    filter: none !important;
}

#chat > .mes .mes_reasoning_details {
    margin-top: 9px;
    color: #4e5653 !important;
    background: rgba(23, 26, 26, 0.035) !important;
    border: 1px solid var(--ef-line) !important;
    border-radius: 0 !important;
}

#chat > .mes .mes_reasoning_summary,
#chat > .mes .mes_reasoning {
    color: inherit !important;
    text-shadow: none !important;
}

#chat > .mes :is(.edit_textarea, .reasoning_edit_textarea) {
    color: var(--ef-ink) !important;
    caret-color: var(--ef-ink) !important;
    background: rgba(255, 255, 255, 0.7) !important;
    border: 1px solid rgba(23, 26, 26, 0.26) !important;
    border-radius: 0 !important;
    box-shadow: inset 3px 0 var(--ef-signal) !important;
}

#chat > .mes .mes_media_wrapper,
#chat > .mes .mes_file_wrapper {
    color: var(--ef-ink) !important;
}

/* User turns become local graphite evidence blocks, never full-width dark cards. */
#chat > .mes[is_user="true"] {
    background: rgba(23, 26, 26, 0.025) !important;
}

#chat > .mes[is_user="true"] > .mes_block {
    margin: 0 0 0 12px;
    padding: 14px 16px 14px 20px !important;
    color: var(--ef-paper-hi) !important;
    background-color: var(--ef-graphite) !important;
    background-image: var(--ef-hatch) !important;
    box-shadow: inset 4px 0 0 var(--ef-signal) !important;
}

#chat > .mes[is_user="true"] > .mes_block .ch_name {
